#include <bits/stdc++.h>
using namespace std;

bool isVowel(char c) {
    return c == 'A' || c == 'E' || c == 'I' ||
           c == 'O' || c == 'U' || c == 'Y';
}

int main() {
    string s;
    cin >> s;

    int ans = 0;
    int previous = -1;

    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        if (isVowel(s[i])) {
            ans = max(ans, i - previous);
            previous = i;
        }
    }

    ans = max(ans, static_cast<int>(s.size()) - previous);
    cout << ans;

    return 0;
}

